// th15_s5_w02 TH15 Stage 5 道中 GirlA02 编队
// 源: st05.ecl.txt MainFront 1340-1350（三次 MainSub01）
//     MainSub01 1472-1485 / GirlA02 148-157 / GirlA02_at 159-174 / GirlA02_at2 176-249
// 源 rank 掩码: !ENH / !L / !LO 分别决定各档参数，下面按 global(GVAR_RANK) 分支。

// 源 etSprite type16 -> TH15_STAR_R，type20 -> TH15_OVAL（0-43 合成映射，半径已核）。
const TH15_STAR_R: int = 608;
const TH15_OVAL: int = 672;

const TIME_LIMIT: int = 2024;
const OPENING_BUFFER: int = 120;

// 源 ANIM a=1 的出生退位移 position -= 4*velocity，初速 0.5 即沿弹向后退 2px。
// 环弹另有 etDist 120，净出生距离 120-2=118。
const BIRTH_BACK: fx = 2fx;
const RING_DIST: fx = 118fx;

// 源 etEx 链（两条分支相同）: ANIM(1) / WAIT 60 / VELTIME(a=120, 方向哨兵 -999999 保留原角)。
// 出生阶段按批准口径省略，独立 WAIT 60 与 VELTIME 斜坡保留。
xformdef SPEED_RAMP(target: fx) {
    @60 add_speed(0fx);
    step_speed(target, 120);
}

// 源 GirlA02_at2。每敌独立任务，自行配置并发射。
// 档位: B=5/10/10/13；单发目标速 4/4/4/6；环 8/8/16/16 颗、目标速 1/1/1/1.4；间隔 20/10/10/8。
async sub girl_a02_fire() {
    var r: int = global(GVAR_RANK);
    var b: int = 5;
    var w: int = 20;
    var ring_n: int = 8;
    var aimed: fx = 4fx;
    var ringv: fx = 1fx;
    if r == 1 || r == 2 {
        b = 10;
        w = 10;
    }
    if r == 2 {
        ring_n = 16;
    }
    if r == 3 {
        b = 13;
        w = 8;
        ring_n = 16;
        aimed = 6fx;
        ringv = 1.4fx;
    }
    wait(2);                        // 源 wait(2)
    var a: int = -1;                // 源 $A = -1
    var k: int = 0;
    while k < b {                   // 源 if ($B--) goto GirlA02_at2_156
        a = a + 1;                  // 源 $A = $A + 1
        if a == 3 {
            // 源 _704: etAim(3) 固定方向环，etAngle(%RANDRAD, 3°) 每发抽一次基角
            var base: int = rand(65536);
            var step: int = 65536 / ring_n;
            var j: int = 0;
            while j < ring_n {
                var ang: angle = (base + j * step) as angle;
                _ = fire(TH15_STAR_R, 2,
                         $self_x + RING_DIST * cos(ang), $self_y + RING_DIST * sin(ang),
                         0.5fx, ang, SPEED_RAMP(ringv), none);
                j = j + 1;
            }
        } else {
            // 源 _156: etAim(0) 自机狙单发，etCount(0,1,1)
            var aim: angle = aim_player();
            _ = fire(TH15_OVAL, 3,
                     $self_x - BIRTH_BACK * cos(aim), $self_y - BIRTH_BACK * sin(aim),
                     0.5fx, aim, SPEED_RAMP(aimed), none);
        }
        wait(w);                    // 源 etOn 后 wait([-1])
        k = k + 1;
    }
}

// 源 GirlA02_at：两值受击/体碰框按普通圆×0.5 换算（24->12, 16->8）。
// 三次移动由父任务按 rank 与镜像换算好后传入。
async sub girl_a02(f0: angle, t1: angle, t2: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn girl_a02_fire();                       // 源 @GirlA02_at2() async
    move_vel(0, f0, 3fx, EASE_LINEAR);           // 源 moveVel(%F0, 3.0f)
    move_vel(120, t1, 2fx, EASE_QUAD_IN);        // 源 moveVelTime(120, 1, -0.19634955f, 2.0f)
    wait(120);                                   // 源 wait(120)
    move_vel(60, t2, 4fx, EASE_QUAD_OUT);        // 源 moveVelTime(60, 4, 2.3561945f, 4.0f)
    loop { wait(1000); }                         // 源 GirlA02_at_248 停驻循环
}

// 源 MainSub01：每次 20 对，%F0 每对抽一次并由左右两只继承；y 各自独立抽取。
sub main_sub01() {
    var i: int = 0;
    while i < 20 {                              // 源 $A = 20 / if ($A--)
        var ra: int = rand(65536);
        var u: fx = (ra - 32768) as fx / 32768;
        // 源 %F0 = 0.3926991f + %RANDF2 * 0.34906584f（22.5° ± 20°）
        var f0: int = 4096 + (3641fx * u) as int;
        var rb: int = rand(65536);
        var ub: fx = (rb - 32768) as fx / 32768;
        var yl: fx = 64fx + 32fx * ub;          // 源 _f(64) + %RANDF2*32
        var rc: int = rand(65536);
        var uc: fx = (rc - 32768) as fx / 32768;
        var yr: fx = 64fx + 32fx * uc;
        // 左: enmCreate；右: enmCreateM（子镜像位1，写入点角度按 π-θ 换算）
        _ = spawn_enemy(-224fx, yl, 50, 0, 1000, 0,
                        girl_a02(f0 as angle, -2048bam, 135deg));
        _ = spawn_enemy(224fx, yr, 50, 0, 1000, 0,
                        girl_a02((32768 - f0) as angle, 34816bam, 45deg));
        wait(20);                               // 源 wait(20)
        i = i + 1;
    }
}

// 源 MainFront 1340-1350：三次 MainSub01，间隔 !ENH wait100 / !L wait70，末尾 !L wait30。
async sub pattern() {
    wait(OPENING_BUFFER);
    main_sub01();
    if global(GVAR_RANK) == 3 { wait(70); } else { wait(100); }
    main_sub01();
    main_sub01();
    if global(GVAR_RANK) == 3 { wait(30); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
